const mongoose=require('mongoose');
 mongoose.connect('mongodb://127.0.0.1:27017/test');//connect will be in
 main().then(()=>{
    console.log("connection successfull");
 })
 .catch(err => console.log(err));

async function main() {
  await mongoose.connect('mongodb://127.0.0.1:27017/test');

  
}
const userschema=new mongoose.Schema({
  name:String,
  email:String,
  age:Number,
})
const user=mongoose.model("User",userschema)//creat collection and also model means its a class used to create documents in collection
//if we command in mongosh we can see extra collection as users because it add s and small letter u 
const user1=new user({
  name:"arun",
  email:"adahd@gmail.com",
  age:32
})
user1.save()
user.insertMany([{name:"hello",email:"iuhtuer@.com",age:23},{name:"bye",email:"hghhg@gmail.com",age:43}])
.then((res)=>{console.log(res)}) //mongoose is operational buffering so we can use before connection established